import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import hashlib
import hmac

app = Flask(__name__)
UPLOAD_DIR = '/tmp/conversions'
SECRET = os.environ.get('HMAC_SECRET', 'default-dev-key')

os.makedirs(UPLOAD_DIR, exist_ok=True)

def verify_signature(data, signature):
    """Verify HMAC signature for API authentication"""
    expected = hmac.new(SECRET.encode(), data, hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature)

@app.route('/api/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.1.4'})

@app.route('/api/convert', methods=['POST'])
def convert_document():
    """Convert uploaded document to PDF using LibreOffice"""
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    uploaded = request.files['file']
    if uploaded.filename == '':
        return jsonify({'error': 'Empty filename'}), 400

    filename = secure_filename(uploaded.filename)
    if not filename:
        return jsonify({'error': 'Invalid filename'}), 400

    # Validate file extension
    allowed_ext = {'doc', 'docx', 'odt', 'rtf', 'txt', 'html', 'htm'}
    ext = filename.rsplit('.', 1)[-1].lower() if '.' in filename else ''
    if ext not in allowed_ext:
        return jsonify({'error': f'Extension .{ext} not allowed'}), 400

    # Save to temp location
    work_dir = tempfile.mkdtemp(dir=UPLOAD_DIR)
    input_path = os.path.join(work_dir, filename)
    uploaded.save(input_path)

    # Get output format from request
    output_format = request.form.get('format', 'pdf')

    # Convert using LibreOffice
    cmd = f'libreoffice --headless --convert-to {output_format} --outdir {work_dir} {input_path}'

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            timeout=30,
            capture_output=True,
            text=True
        )

        if result.returncode != 0:
            return jsonify({'error': 'Conversion failed', 'detail': result.stderr[:200]}), 500

        # Find output file
        output_name = filename.rsplit('.', 1)[0] + '.' + output_format.split(':')[0]
        output_path = os.path.join(work_dir, output_name)

        if not os.path.exists(output_path):
            return jsonify({'error': 'Output file not generated'}), 500

        return send_file(output_path, as_attachment=True, download_name=output_name)

    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Conversion timed out'}), 504
    finally:
        # Cleanup handled by cron job
        pass

@app.route('/api/batch', methods=['POST'])
def batch_convert():
    """Batch conversion endpoint - accepts JSON manifest"""
    manifest = request.get_json()
    if not manifest or 'files' not in manifest:
        return jsonify({'error': 'Invalid manifest'}), 400

    # Validate manifest structure
    if len(manifest['files']) > 10:
        return jsonify({'error': 'Maximum 10 files per batch'}), 400

    results = []
    for entry in manifest['files']:
        if 'url' not in entry:
            results.append({'status': 'error', 'reason': 'missing url'})
            continue
        # Queue for async processing
        job_id = hashlib.md5(entry['url'].encode()).hexdigest()[:12]
        results.append({'status': 'queued', 'job_id': job_id})

    return jsonify({'batch_id': os.urandom(8).hex(), 'results': results})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
